export const figureSourceScale = .26;
export const figureAnchor = [120, 175];
const safePrefix = prefix => String(prefix).replace(/[^a-zA-Z0-9_-]/g, '') || 'koralli-company-building';

/** Define each editable figure once within its own building SVG. */
export function figureDefinitions(prefix = 'koralli-company-building') {
  const id = safePrefix(prefix);
  return `<defs data-figure-definitions="revision-07">${Object.entries(figures).map(([name,body]) => `<g id="${id}-figure-${name}" data-source-figure="${name}">${body}</g>`).join('')}</defs>`;
}

/** The original Figma viewport is 240x300; local world-foot origin is (120,175). */
export function figureMarkup(kind = 'man', pose = 'standing', prefix = 'koralli-company-building') {
  const name = `${kind}-${pose}`;
  if (!(name in figures)) throw new RangeError('Unknown revision-07 figure: ' + name);
  return `<g data-figure="${kind}" data-pose="${pose}" transform="scale(${figureSourceScale}) translate(-120 -175)"><use href="#${safePrefix(prefix)}-figure-${name}"/></g>`;
}
